from src.ledger import balances, monthly_totals, statement

def test_balances_basic():
    lines = ["2026-01-01,cash,100.00", "2026-01-02,cash,-40.00", "2026-01-02,bank,10.00"]
    assert balances(lines) == {"cash": 60.0, "bank": 10.0}


def test_statement_accumulates_chronologically_for_unsorted_input():
    lines = ["2026-01-03,cash,-40.00", "2026-01-01,cash,100.00", "2026-01-02,bank,10.00"]
    assert statement(lines, "cash") == [("2026-01-01", 100.0), ("2026-01-03", 60.0)]


def test_statement_keeps_file_order_within_a_date():
    lines = ["2026-01-02,cash,5.00", "2026-01-01,cash,100.00", "2026-01-02,cash,-40.00"]
    assert statement(lines, "cash") == [
        ("2026-01-01", 100.0),
        ("2026-01-02", 105.0),
        ("2026-01-02", 65.0),
    ]


def test_statement_skips_comments_and_blank_lines():
    lines = ["# opening", "", "2026-01-02,cash,-40.00", "  # note", "2026-01-01,cash,100.00"]
    assert statement(lines, "cash") == [("2026-01-01", 100.0), ("2026-01-02", 60.0)]


def test_monthly_totals_are_chronological_for_unsorted_input():
    lines = [
        "2026-03-01,cash,5.00",
        "2026-01-01,cash,100.00",
        "2026-02-01,cash,-40.00",
        "2026-01-15,cash,1.00",
        "2026-02-02,bank,99.00",
    ]
    assert monthly_totals(lines, "cash") == [
        ("2026-01", 101.0),
        ("2026-02", -40.0),
        ("2026-03", 5.0),
    ]


def test_monthly_totals_sort_across_year_boundary():
    lines = ["2026-01-01,cash,1.00", "2025-12-31,cash,2.00"]
    assert monthly_totals(lines, "cash") == [("2025-12", 2.0), ("2026-01", 1.0)]
